* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1e1e2f;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: #e0e0e0;
  padding: 16px;
}

.game {
  background: #2a2a40;
  padding: 24px 16px;
  border-radius: 16px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  width: 100%;
  max-width: 480px;
  text-align: center;
}

h1 {
  font-size: 1.6rem;
  margin-bottom: 12px;
  color: #f0c040;
  letter-spacing: 1px;
}

.moves {
  margin-bottom: 16px;
  font-size: 1.1rem;
  color: #b0b0c0;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 20px;
}

.card {
  aspect-ratio: 1 / 1;
  background: #3a3a55;
  border: 2px solid #55557a;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: transparent;
  user-select: none;
}

.card::before {
  content: '?';
  color: #8888aa;
  font-weight: bold;
}

.card.flipped {
  background: #4a4a6a;
  border-color: #f0c040;
  transform: scale(1.02);
}

.card.flipped::before {
  content: '';
}

.card.matched {
  background: #2e7d32;
  border-color: #4caf50;
  cursor: default;
  transform: none;
}

.card.matched::before {
  content: '';
}

.card:focus-visible {
  outline: 3px solid #f0c040;
  outline-offset: 2px;
}

.card:hover:not(.matched):not(.flipped) {
  background: #4a4a6a;
  border-color: #8888aa;
}

.card:active:not(.matched):not(.flipped) {
  transform: scale(0.95);
}

.new-game {
  background: #f0c040;
  color: #1e1e2f;
  border: none;
  border-radius: 8px;
  padding: 12px 28px;
  font-size: 1.1rem;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.new-game:hover {
  background: #ffd966;
}

.new-game:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.new-game:active {
  transform: scale(0.95);
}

.win-message {
  margin: 12px 0;
  font-size: 1.2rem;
  color: #4caf50;
  min-height: 1.5em;
}

@media (max-width: 400px) {
  .board {
    gap: 6px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .game {
    padding: 16px 12px;
  }
}

const COLORS = [
  '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
  '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
];

const board = document.getElementById('board');
const moveCountEl = document.getElementById('moveCount');
const winMessage = document.getElementById('winMessage');
const newGameBtn = document.getElementById('newGameBtn');

let deck = [];
let flipped = [];
let matched = 0;
let moves = 0;
let lock = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createDeck() {
  const cards = [];
  COLORS.forEach((color, index) => {
    cards.push({ color, pairId: index });
    cards.push({ color, pairId: index });
  });
  return shuffle(cards);
}

function renderBoard() {
  board.innerHTML = '';
  deck.forEach((card, i) => {
    const btn = document.createElement('button');
    btn.className = 'card';
    btn.type = 'button';
    btn.setAttribute('aria-label', `Card ${i + 1}`);
    btn.dataset.index = i;
    btn.addEventListener('click', () => flipCard(i, btn));
    board.appendChild(btn);
  });
}

function flipCard(index, btn) {
  if (lock || btn.classList.contains('flipped') || btn.classList.contains('matched')) return;
  btn.classList.add('flipped');
  btn.style.background = deck[index].color;
  btn.setAttribute('aria-label', `Card ${index + 1} flipped`);
  flipped.push({ index, btn });

  if (flipped.length === 2) {
    moves++;
    moveCountEl.textContent = moves;
    lock = true;

    const [a, b] = flipped;
    if (deck[a.index].pairId === deck[b.index].pairId) {
      setTimeout(() => {
        a.btn.classList.add('matched');
        b.btn.classList.add('matched');
        a.btn.setAttribute('aria-label', `Card ${a.index + 1} matched`);
        b.btn.setAttribute('aria-label', `Card ${b.index + 1} matched`);
        matched++;
        flipped = [];
        lock = false;
        if (matched === COLORS.length) {
          winMessage.textContent = `You won in ${moves} moves!`;
        }
      }, 300);
    } else {
      setTimeout(() => {
        a.btn.classList.remove('flipped');
        b.btn.classList.remove('flipped');
        a.btn.style.background = '';
        b.btn.style.background = '';
        a.btn.setAttribute('aria-label', `Card ${a.index + 1}`);
        b.btn.setAttribute('aria-label', `Card ${b.index + 1}`);
        flipped = [];
        lock = false;
      }, 800);
    }
  }
}

function resetGame() {
  deck = createDeck();
  flipped = [];
  matched = 0;
  moves = 0;
  lock = false;
  moveCountEl.textContent = '0';
  winMessage.textContent = '';
  renderBoard();
  newGameBtn.focus();
}

newGameBtn.addEventListener('click', resetGame);
resetGame();
